import uuid from 'react-native-uuid';
export const confirmLoanRegister = createAsyncThunk(
    'loanRegister/confirm',
    async (payload: RegisterLoanDemandPayload['data']) => {
        const loanDemand = container.get<RegisterLoanDemandHandler>(TYPES.RegisterLoanDemandHandler);
        const query = new Query<RegisterLoanDemandPayload>({
            query: {
                "requestId": uuid.v4(),
                "channel": "Mobile",
                "ipRequest": "128.0.0.1",
                "language": "vn",
                "deviceInfo": {
                    "deviceId": "123-1232-123",
                    "deviceName": "Testing",
                    "os": "IOS",
                    "osVersion": "15"
                },
                "data": payload
            },
        });
        return await loanDemand.handle(query);
    },
);

