import React, { useEffect, useRef } from 'react';
import { View } from 'react-native';
import { BottomSheetManager, BottomSheet, BottomSheetRef } from '@core/ui';
import { ScrollView } from 'react-native-gesture-handler';
import MonthSlider from '../slider/MonthSlider';
import { IS_IOS } from '@core/service';

interface BottomSheetInputProps {
    onSubmit?: (value: number) => void;
    show: boolean;
    title: string;
    onClose?: () => void;
    min: number;
    max: number;
    value: number;
}

const BottomSheetSlider = (props: BottomSheetInputProps) => {
    const { onSubmit, title, show, onClose, min, max, value } = props;
    const bsRef = useRef<BottomSheetRef>(null);

    const handleSubmit = (value: number) => {
        onSubmit?.(value);
        bsRef.current?.close();
    };
    const onShowModal = () => {
        BottomSheetManager.show({
            render: (portalId) => (
                <BottomSheet ref={bsRef} id={portalId} title={title} description='' onClose={onClose} enableContentPanningGesture={false} adjustKeyboard={false} android_keyboardInputMode='adjustResize' safeAreaBottomOffset={IS_IOS ? 370 : undefined} snapPoints={['65%']}>
                    <ScrollView keyboardShouldPersistTaps='handled'>
                        <MonthSlider min={min} max={max} value={value} onSubmit={handleSubmit} />
                    </ScrollView>
                </BottomSheet>
            )
        });
    };

    useEffect(() => {
        if (show) {
            onShowModal();
        }
    }, [show]);
    return (
        <View></View>
    );
};

export default BottomSheetSlider;
